/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s behaviour:
 *   - one command line argument, a Roman numeral (case‑insensitive)
 *   - if the argument is a valid canonical Roman numeral (1 … 3999)
 *     print its integer value followed by a newline
 *   - otherwise print the literal string "INVALID"
 *
 * The program follows the exact checks observed in the decompiled
 * binary: missing argument, length > 63, characters outside
 * {I,V,X,L,C,D,M}, value out of range, and non‑canonical form.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63
#define MAX_ROMAN     3999

/* Symbol/value tables used for both parsing and canonical generation */
static const struct {
    const char *sym;
    int value;
} roman_table[] = {
    {"M",  1000},
    {"CM",  900},
    {"D",   500},
    {"CD",  400},
    {"C",   100},
    {"XC",   90},
    {"L",    50},
    {"XL",   40},
    {"X",    10},
    {"IX",    9},
    {"V",     5},
    {"IV",    4},
    {"I",     1}
};

/* Convert a single Roman character to its numeric value.
   Returns -1 for any character that is not a Roman symbol. */
static int char_value(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

/* Build the canonical Roman representation of a value (1 … 3999). */
static void int_to_roman(int n, char *out)
{
    char *p = out;
    for (size_t i = 0; i < sizeof roman_table / sizeof roman_table[0]; ++i) {
        while (n >= roman_table[i].value) {
            const char *sym = roman_table[i].sym;
            while (*sym) *p++ = *sym++;
            n -= roman_table[i].value;
        }
    }
    *p = '\0';
}

/* Parse a Roman numeral string.
   Returns the integer value on success, -1 on any error. */
static int parse_roman(const char *s)
{
    int total = 0;
    int prev = 0;               /* value of the previous symbol */

    while (*s) {
        int cur = char_value(*s);
        if (cur == -1)               /* illegal character */
            return -1;

        /* Standard left‑to‑right evaluation:
           if a smaller value precedes a larger one we subtract,
           otherwise we add. */
        if (cur > prev)
            total += cur - 2 * prev;   /* undo the previous addition */
        else
            total += cur;

        prev = cur;
        ++s;
    }

    if (total <= 0 || total > MAX_ROMAN)
        return -1;

    return total;
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    if (len == 0 || len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* Convert to upper‑case into a temporary buffer */
    char upper[MAX_INPUT_LEN + 1];
    for (size_t i = 0; i < len; ++i) {
        char c = input[i];
        if ('a' <= c && c <= 'z')
            c = (char)(c - ('a' - 'A'));
        upper[i] = c;
    }
    upper[len] = '\0';

    /* Parse the numeral */
    int value = parse_roman(upper);
    if (value == -1) {
        puts("INVALID");
        return 0;
    }

    /* Re‑generate the canonical form and compare */
    char canonical[64];
    int_to_roman(value, canonical);
    if (strcmp(upper, canonical) != 0) {
        puts("INVALID");
        return 0;
    }

    printf("%d\n", value);
    return 0;
}
